(function(){
  'use strict';

  // Future secure services connect here. Never place private API keys in this file.
  window.SourceLabConfig={mode:'frontend-demo',apiBaseUrl:'',checkoutSessionEndpoint:'',accountSessionEndpoint:''};

  const icons={search:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6.5"></circle><path d="m16 16 4 4"></path></svg>',user:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.5"></circle><path d="M5 20c.6-4 3.1-6 7-6s6.4 2 7 6"></path></svg>',bag:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8h14l-1 12H6L5 8Z"></path><path d="M9 9V6a3 3 0 0 1 6 0v3"></path></svg>',menu:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"></path></svg>',close:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"></path></svg>'};
  const navItems=[['Home','index.html'],['Products','products.html'],['Suppliers','suppliers.html'],['About','about.html']];
  const current=location.pathname.split('/').pop()||'index.html';

  function header(){return `<header class="site-header"><nav class="nav-shell" aria-label="Primary navigation"><a class="brand" href="index.html" aria-label="SourceLab home"><img src="assets/logo/sourcelab-logo-transparent.png" alt="SourceLab"></a><div class="nav-links" id="nav-links">${navItems.map(([label,href])=>`<a href="${href}" ${current===href?'aria-current="page"':''}>${label}</a>`).join('')}</div><div class="nav-actions"><button class="icon-button" type="button" data-open-search aria-label="Search">${icons.search}</button><a class="icon-button" href="account.html" aria-label="Account">${icons.user}</a><button class="cart-button" type="button" data-open-cart aria-label="Open cart">${icons.bag}<span data-cart-count>0</span></button><button class="menu-button" type="button" data-menu-button aria-label="Open menu" aria-expanded="false">${icons.menu}<span>Menu</span></button></div></nav><div class="mobile-nav" data-mobile-nav><p>Menu</p>${navItems.map(([label,href])=>`<a href="${href}">${label}</a>`).join('')}<a href="contact.html">Contact</a><a href="account.html">Workspace</a></div></header>`;}
  function footer(){return `<footer class="site-footer"><div class="footer-statement shell"><p>SourceLab</p><h2>Source <span>better.</span><br>Sell <span>smarter.</span></h2><a class="button button-primary" href="products.html">Browse products</a></div><div class="footer-grid shell"><div class="footer-intro"><a class="footer-brand" href="index.html"><img src="assets/logo/sourcelab-logo-transparent.png" alt="SourceLab"></a><p>Products, supplier research and practical tools for resellers.</p></div><div><p>Shop</p><a href="products.html">Products</a><a href="suppliers.html">Supplier Hub</a><a href="cart.html">Cart</a></div><div><p>SourceLab</p><a href="about.html">About</a><a href="index.html#faq">Questions</a><a href="account.html">Workspace</a></div><div><p>Support</p><a href="contact.html">Contact</a><a href="account.html">Account</a></div><div><p>Information</p><a href="about.html">Terms</a><a href="about.html">Privacy</a></div></div><div class="footer-bottom shell"><span>© 2026 SourceLab</span><span>Static demo</span></div></footer>`;}
  function overlays(){return `<div class="overlay" data-overlay></div><aside class="cart-drawer" data-cart-drawer aria-hidden="true" aria-label="Shopping cart"><div class="drawer-head"><div><small>Your cart</small><h2>Cart <span data-cart-count>0</span></h2></div><button class="icon-button" data-close-cart aria-label="Close cart">${icons.close}</button></div><div class="drawer-content" data-cart-drawer-content></div></aside><div class="search-modal" data-search-modal role="dialog" aria-modal="true" aria-labelledby="search-title" aria-hidden="true"><div class="search-shell"><div class="search-head"><div><small>Search SourceLab</small><h2 id="search-title">Search</h2></div><button class="icon-button" data-close-search aria-label="Close search">${icons.close}</button></div><label class="search-input">${icons.search}<input type="search" data-global-search placeholder="Search products and suppliers" autocomplete="off"></label><div class="search-results" data-search-results><div class="search-empty"><p>Search by product, supplier or category.</p><div><button data-search-suggestion="pricing">Pricing</button><button data-search-suggestion="clothing">Clothing</button><button data-search-suggestion="electronics">Electronics</button></div></div></div></div></div><div class="toast-region" data-toast-region aria-live="polite" aria-atomic="true"></div>`;}

  function initShell(){document.querySelectorAll('[data-site-header]').forEach(node=>node.outerHTML=header());document.querySelectorAll('[data-site-footer]').forEach(node=>node.outerHTML=footer());document.body.insertAdjacentHTML('beforeend',overlays());window.SourceLabCart?.update();}
  const overlay=()=>document.querySelector('[data-overlay]');
  function setOverlay(open){overlay().classList.toggle('open',open);document.body.classList.toggle('no-scroll',open);}
  function openCart(){const drawer=document.querySelector('[data-cart-drawer]');drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');setOverlay(true);drawer.querySelector('[data-close-cart]').focus();}
  function closeCart(){const drawer=document.querySelector('[data-cart-drawer]');drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');setOverlay(false);}
  function openSearch(){const modal=document.querySelector('[data-search-modal]');modal.classList.add('open');modal.setAttribute('aria-hidden','false');setOverlay(true);setTimeout(()=>modal.querySelector('input').focus(),50);}
  function closeSearch(){const modal=document.querySelector('[data-search-modal]');modal.classList.remove('open');modal.setAttribute('aria-hidden','true');setOverlay(false);}
  function toast(message){const region=document.querySelector('[data-toast-region]');if(!region)return;const item=document.createElement('div');item.className='toast';item.innerHTML=`<span>✓</span>${message}`;region.append(item);requestAnimationFrame(()=>item.classList.add('show'));setTimeout(()=>{item.classList.remove('show');setTimeout(()=>item.remove(),250)},2800);}

  function search(query){const results=document.querySelector('[data-search-results]');const term=query.trim().toLowerCase();if(!term){results.innerHTML='<div class="search-empty"><p>Search by product, supplier or category.</p><div><button data-search-suggestion="pricing">Pricing</button><button data-search-suggestion="clothing">Clothing</button><button data-search-suggestion="electronics">Electronics</button></div></div>';return;}const data=window.SourceLabData;const matches=[...data.products.map(x=>({...x,type:'Product',url:`product.html?id=${x.id}`})),...data.suppliers.map(x=>({...x,type:'Supplier',url:`supplier.html?id=${x.id}`}))].filter(item=>`${item.title} ${item.category||''} ${item.description||''}`.toLowerCase().includes(term)).slice(0,8);results.innerHTML=matches.length?matches.map(item=>`<a class="search-result" href="${item.url}"><span>${item.type}</span><strong>${item.title}</strong><small>${item.category||''}</small></a>`).join(''):'<div class="empty-state compact"><h3>No results</h3><p>Try another product or category.</p></div>';}

  function initEvents(){document.addEventListener('click',event=>{if(event.target.closest('[data-open-cart]'))openCart();if(event.target.closest('[data-close-cart]'))closeCart();if(event.target.closest('[data-open-search]'))openSearch();if(event.target.closest('[data-close-search]'))closeSearch();if(event.target.closest('[data-overlay]')){closeCart();closeSearch();}const menu=event.target.closest('[data-menu-button]');if(menu){const open=document.querySelector('[data-mobile-nav]').classList.toggle('open');menu.setAttribute('aria-expanded',open?'true':'false');menu.innerHTML=(open?icons.close:icons.menu)+`<span>${open?'Close':'Menu'}</span>`;}const faq=event.target.closest('[data-faq-button]');if(faq){const item=faq.closest('.faq-item');const open=item.classList.toggle('open');faq.setAttribute('aria-expanded',open?'true':'false');}const tab=event.target.closest('[data-tab-target]');if(tab){const tabs=tab.closest('[data-tabs]');tabs.querySelectorAll('[data-tab-target]').forEach(btn=>btn.classList.toggle('active',btn===tab));tabs.querySelectorAll('[data-tab-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.tabPanel===tab.dataset.tabTarget));}const suggestion=event.target.closest('[data-search-suggestion]');if(suggestion){const input=document.querySelector('[data-global-search]');input.value=suggestion.dataset.searchSuggestion;search(input.value);}if(event.target.closest('[data-newsletter-submit]')){event.preventDefault();const form=event.target.closest('form');const input=form.querySelector('input');if(input.checkValidity()){toast('You are on the demo list');input.value='';}else input.reportValidity();}});
    document.querySelector('[data-global-search]').addEventListener('input',e=>search(e.target.value));document.querySelector('[data-contact-form]')?.addEventListener('submit',event=>{event.preventDefault();if(event.currentTarget.checkValidity()){toast('Demo enquiry ready for API connection');event.currentTarget.reset();}else event.currentTarget.reportValidity();});document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeCart();closeSearch();}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();}});
  }

  function observeReveals(){const items=document.querySelectorAll('.reveal:not(.observed)');if(!('IntersectionObserver'in window)){items.forEach(item=>item.classList.add('visible'));return;}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.08});items.forEach(item=>{item.classList.add('observed');observer.observe(item);});}
  function initMotion(){
    const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
    requestAnimationFrame(()=>document.body.classList.add('is-ready'));
    const header=document.querySelector('.site-header');
    const process=document.querySelector('[data-process]');
    const processSteps=process?[...process.querySelectorAll('.process-list li')]:[];
    let scheduled=false;
    const update=()=>{scheduled=false;header?.classList.toggle('scrolled',scrollY>24);document.documentElement.style.setProperty('--scroll-y',`${scrollY}px`);if(process){const rect=process.getBoundingClientRect();const span=Math.max(1,rect.height-innerHeight*.35);const progress=Math.max(0,Math.min(1,(innerHeight*.55-rect.top)/span));process.style.setProperty('--process-progress',progress);const active=Math.min(processSteps.length-1,Math.max(0,Math.floor(progress*processSteps.length)));processSteps.forEach((step,index)=>step.classList.toggle('active',index===active));}};
    addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(update)}},{passive:true});update();
    if(!reduced){
      const layers=[...document.querySelectorAll('[data-parallax]')];
      let parallaxFrame=false;
      const move=()=>{parallaxFrame=false;layers.forEach(layer=>{const rect=layer.getBoundingClientRect();const amount=Number(layer.dataset.parallax||.02);layer.style.setProperty('--parallax',`${(innerHeight/2-rect.top-rect.height/2)*amount}px`);});};
      addEventListener('scroll',()=>{if(!parallaxFrame){parallaxFrame=true;requestAnimationFrame(move)}},{passive:true});move();
      document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(!link||link.target==='_blank'||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const url=new URL(link.href,location.href);if(url.origin!==location.origin||url.pathname===location.pathname&&url.hash)return;event.preventDefault();document.body.classList.add('is-leaving');setTimeout(()=>location.href=link.href,180);});
    }
  }
  function initPage(){document.querySelectorAll('[data-tabs]').forEach(tabs=>{if(!tabs.querySelector('[data-tab-target].active'))tabs.querySelector('[data-tab-target]')?.classList.add('active');});observeReveals();initMotion();window.SourceLabCart?.refreshWishlist();}

  window.SourceLabUI={toast,openCart,closeCart,openSearch,closeSearch,observeReveals,refreshWishlist:()=>window.SourceLabCart?.refreshWishlist()};
  function init(){initShell();initEvents();initPage();}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
